(function(){
  // product data + order builder
  const CRUNCH_IMG = "data:image/png;base64,";
  const MILLET_IMG = "data:image/png;base64,";
  const OATS_IMG = "data:image/png;base64,";
  const RAGI_IMG = "data:image/png;base64,";
  const QUINOA_IMG = "data:image/png;base64,";

  const products = [
    { name:"12X Crunch", grams:"100g", price:120, cat:"crunch", img:CRUNCH_IMG },
    { name:"12X Crunch", grams:"200g", price:210, cat:"crunch", img:CRUNCH_IMG },
    { name:"12X Crunch", grams:"300g", price:299, cat:"crunch", img:CRUNCH_IMG },
    { name:"12X Crunch", grams:"500g", price:550, cat:"crunch", img:CRUNCH_IMG },
    { name:"12X Crunch", grams:"1kg",  price:1000, cat:"crunch", img:CRUNCH_IMG },
    { name:"Multi Millet Chips", grams:"80g", price:120, cat:"chips", img:MILLET_IMG },
    { name:"Oats Chips", grams:"80g", price:120, cat:"chips", img:OATS_IMG },
    { name:"Quinoa Chips", grams:"80g", price:120, cat:"chips", img:QUINOA_IMG },
    { name:"Ragi Chips", grams:"80g", price:120, cat:"chips", img:RAGI_IMG },
    { name:"Quinoa Flakes Mix", grams:"100g", price:120, cat:"mixes" },
    { name:"Nutri Nuts", grams:"100g", price:120, cat:"nuts" },
    { name:"Mexican Bites", grams:"100g", price:120, cat:"mixes" },
    { name:"Pro Beans", grams:"100g", price:120, cat:"nuts" },
    { name:"Millet Mixture (Puff)", grams:"200g", price:150, cat:"mixes" },
    { name:"Quinoa Flakes Mix", grams:"200g", price:250, cat:"mixes" },
    { name:"Nutri Nuts", grams:"250g", price:250, cat:"nuts" },
    { name:"Mexican Bites", grams:"250g", price:250, cat:"mixes" },
    { name:"Pro Beans", grams:"250g", price:250, cat:"nuts" }
  ];

  const placeholderIcon = '<div class="card-img-wrap placeholder"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 20V10l8-6 8 6v10"/><path d="M9 20v-6h6v6"/></svg></div>';
  const zoomHint = '<span class="card-zoom-hint"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M1.5 12S5 5 12 5s10.5 7 10.5 7-3.5 7-10.5 7S1.5 12 1.5 12Z"/><circle cx="12" cy="12" r="3"/></svg></span>';

  const grid = document.getElementById("item-grid");
  const qty = new Array(products.length).fill(0);
  const PHONE = "918341383888";
  const rupee = n => "\u20b9" + n.toLocaleString("en-IN");

  // Quantity-based discount: 1 item = full price, each extra item adds 3% off,
  // capped at 30% so the discount never runs away at very large quantities.
  const DISCOUNT_STEP = 3;
  const DISCOUNT_CAP = 30;
  function discountPercent(q){
    if(q <= 1) return 0;
    return Math.min((q - 1) * DISCOUNT_STEP, DISCOUNT_CAP);
  }
  function unitPriceFor(basePrice, q){
    const pct = discountPercent(q);
    const unit = Math.round(basePrice * (1 - pct / 100));
    return { unit, pct };
  }

  // Group same-name products (different pack sizes) into one card with a
  // size selector, instead of a separate card per size.
  const groups = [];
  const groupMap = {};
  products.forEach((p, i) => {
    if(!(p.name in groupMap)){
      groupMap[p.name] = groups.length;
      groups.push({ name: p.name, cat: p.cat, img: p.img, variants: [i] });
    } else {
      groups[groupMap[p.name]].variants.push(i);
    }
  });

  function footerHTML(i){
    return '<div class="price-cell" id="price-' + i + '"><span class="price-now">' + rupee(products[i].price) + '</span></div>' +
      '<div class="qty-stepper">' +
        '<button type="button" aria-label="Decrease quantity" data-action="dec" data-i="' + i + '">\u2212</button>' +
        '<span id="qty-' + i + '">' + qty[i] + '</span>' +
        '<button type="button" aria-label="Increase quantity" data-action="inc" data-i="' + i + '">+</button>' +
      '</div>';
  }

  function updateSizePillLabel(i){
    const pill = grid.querySelector('.size-pill[data-size-i="' + i + '"]');
    if(!pill) return;
    const base = products[i].grams;
    pill.textContent = qty[i] > 0 ? base + " (" + qty[i] + ")" : base;
    pill.classList.toggle("has-qty", qty[i] > 0);
  }

  groups.forEach((g, gi) => {
    const card = document.createElement("div");
    card.className = "product-card";
    card.dataset.cat = g.cat;
    const activeIdx = g.variants[0];
    card.dataset.active = activeIdx;

    const imgBlock = g.img
      ? '<button type="button" class="card-img-wrap" data-img="' + g.img + '" data-name="' + g.name + '" aria-label="View image of ' + g.name + '"><img src="' + g.img + '" alt="' + g.name + '" loading="lazy">' + zoomHint + '</button>'
      : placeholderIcon;

    const sizeMarkup = g.variants.length > 1
      ? '<div class="size-pills">' + g.variants.map((idx, vi) =>
          '<button type="button" class="size-pill' + (vi === 0 ? " active" : "") + '" data-size-i="' + idx + '" data-gi="' + gi + '">' + products[idx].grams + '</button>'
        ).join("") + '</div>'
      : '<p class="card-grams">' + products[activeIdx].grams + '</p>';

    card.innerHTML =
      imgBlock +
      '<div class="card-body">' +
        '<p class="card-name">' + g.name + '</p>' +
        sizeMarkup +
        '<div class="card-footer" id="footer-g' + gi + '">' + footerHTML(activeIdx) + '</div>' +
      '</div>';
    grid.appendChild(card);
  });

  function renderPriceCell(i){
    const p = products[i];
    const cell = document.getElementById("price-" + i);
    const { unit, pct } = unitPriceFor(p.price, qty[i]);
    if(pct > 0){
      cell.innerHTML =
        '<span class="price-old">' + rupee(p.price) + '</span>' +
        '<span class="price-now">' + rupee(unit) + '</span>' +
        '<span class="price-off">' + pct + '% off</span>';
    } else {
      cell.innerHTML = '<span class="price-now">' + rupee(p.price) + '</span>';
    }
  }

  grid.addEventListener("click", function(e){
    const viewBtn = e.target.closest(".card-img-wrap[data-img]");
    if(viewBtn){
      openLightbox(viewBtn.dataset.img, viewBtn.dataset.name);
      return;
    }

    const sizeBtn = e.target.closest(".size-pill");
    if(sizeBtn){
      const gi = sizeBtn.dataset.gi;
      const newIdx = Number(sizeBtn.dataset.sizeI);
      const card = sizeBtn.closest(".product-card");
      card.dataset.active = newIdx;
      card.querySelectorAll(".size-pill").forEach(b => b.classList.toggle("active", b === sizeBtn));
      document.getElementById("footer-g" + gi).innerHTML = footerHTML(newIdx);
      renderPriceCell(newIdx);
      return;
    }

    const btn = e.target.closest("button[data-action]");
    if(!btn) return;
    const i = Number(btn.dataset.i);
    if(btn.dataset.action === "inc") qty[i]++;
    if(btn.dataset.action === "dec") qty[i] = Math.max(0, qty[i] - 1);
    document.getElementById("qty-" + i).textContent = qty[i];
    renderPriceCell(i);
    updateSizePillLabel(i);
    updateOrder();
  });

  // image lightbox
  const lightbox = document.getElementById("lightbox");
  const lightboxImg = document.getElementById("lightbox-img");
  const lightboxCaption = document.getElementById("lightbox-caption");
  const lightboxClose = document.getElementById("lightbox-close");

  function openLightbox(src, name){
    lightboxImg.src = src;
    lightboxImg.alt = name || "";
    lightboxCaption.textContent = name || "";
    lightbox.classList.add("open");
    document.body.style.overflow = "hidden";
  }
  function closeLightbox(){
    lightbox.classList.remove("open");
    document.body.style.overflow = "";
  }
  lightboxClose.addEventListener("click", closeLightbox);
  lightbox.addEventListener("click", function(e){
    if(e.target === lightbox) closeLightbox();
  });
  document.addEventListener("keydown", function(e){
    if(e.key === "Escape") closeLightbox();
  });

  const tabs = document.getElementById("tabs");
  tabs.addEventListener("click", function(e){
    const btn = e.target.closest(".tab-btn");
    if(!btn) return;
    tabs.querySelectorAll(".tab-btn").forEach(b => {
      b.classList.remove("active");
      b.setAttribute("aria-selected", "false");
    });
    btn.classList.add("active");
    btn.setAttribute("aria-selected", "true");
    const cat = btn.dataset.cat;
    grid.querySelectorAll(".product-card").forEach(card => {
      card.classList.toggle("hidden-card", cat !== "all" && card.dataset.cat !== cat);
    });
  });

  const orderBtn = document.getElementById("order-btn");
  const orderLabel = document.getElementById("order-label");
  const ctaNote = document.getElementById("cta-note");
  const pill = document.getElementById("order-pill");
  const pillCount = document.getElementById("pill-count");
  const pillText = document.getElementById("pill-text");
  const baseText = "Hi, I'd like to order from Vasista Food and Traders";

  // ---- Payment (UPI) config — replace UPI_ID with the real business UPI ID ----
  const UPI_ID = "8712573832@ybl";
  const UPI_PAYEE_NAME = "Vaddi Venkat Nishant Reddy";

  // ---- Order logging to Google Sheets ----
  // Paste the "Web app URL" you get after deploying the Apps Script (see setup
  // guide) here. Leave it as-is and logging is silently skipped — nothing else
  // on the site depends on this.
  const ORDER_LOG_URL = "https://script.google.com/macros/s/AKfycbziWEBVPUSk1RUIt2gwM_y3c0MWcHUYQ8CRifGpvQKz-ozawUD5NmpIJuL8B5qH5hAw/exec";

  const custFields = {
    name: document.getElementById("cust-name"),
    phone: document.getElementById("cust-phone"),
    address: document.getElementById("cust-address"),
    city: document.getElementById("cust-city"),
    pincode: document.getElementById("cust-pincode"),
    landmark: document.getElementById("cust-landmark")
  };
  const upiRefInput = document.getElementById("upi-ref");
  const upiPanel = document.getElementById("upi-panel");
  const upiQrImg = document.getElementById("upi-qr");
  const upiIdText = document.getElementById("upi-id-text");
  const copyUpiBtn = document.getElementById("copy-upi-btn");
  const deliverySection = document.getElementById("delivery-section");
  const deliveryErrorBanner = document.getElementById("delivery-error-banner");
  const payRadios = document.querySelectorAll('input[name="pay-method"]');

  upiIdText.textContent = UPI_ID;
  let currentTotal = 0;

  function getCartSummary(){
    let total = 0, count = 0;
    const lines = [];
    products.forEach((p, i) => {
      if(qty[i] > 0){
        count += qty[i];
        const { unit, pct } = unitPriceFor(p.price, qty[i]);
        total += qty[i] * unit;
        let line = p.name + " (" + p.grams + ") x" + qty[i] + " @ " + rupee(unit);
        if(pct > 0) line += " (" + pct + "% off)";
        lines.push(line);
      }
    });
    return { total, count, lines };
  }

  function currentPayMethod(){
    const checked = document.querySelector('input[name="pay-method"]:checked');
    return checked ? checked.value : "cod";
  }

  function updateUpiQr(total){
    const upiUrl = "upi://pay?pa=" + encodeURIComponent(UPI_ID) +
                   "&pn=" + encodeURIComponent(UPI_PAYEE_NAME) +
                   (total > 0 ? "&am=" + total : "") +
                   "&cu=INR&tn=" + encodeURIComponent("Vasista order");
    upiQrImg.src = "https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=" + encodeURIComponent(upiUrl);
    upiQrImg.alt = total > 0 ? "Scan to pay " + rupee(total) + " via UPI" : "Scan to pay via UPI";
  }

  payRadios.forEach(r => r.addEventListener("change", function(){
    const isUpi = currentPayMethod() === "upi";
    upiPanel.classList.toggle("hidden", !isUpi);
    if(isUpi) updateUpiQr(currentTotal);
  }));

  copyUpiBtn.addEventListener("click", function(){
    if(navigator.clipboard){
      navigator.clipboard.writeText(UPI_ID).then(function(){
        copyUpiBtn.textContent = "Copied!";
        setTimeout(function(){ copyUpiBtn.textContent = "Copy"; }, 1500);
      });
    }
  });

  function setFieldInvalid(fieldId, invalid){
    const el = document.getElementById(fieldId);
    if(el) el.classList.toggle("invalid", invalid);
  }

  function validateDelivery(){
    const vals = {
      name: custFields.name.value.trim(),
      phone: custFields.phone.value.trim(),
      address: custFields.address.value.trim(),
      city: custFields.city.value.trim(),
      pincode: custFields.pincode.value.trim(),
      landmark: custFields.landmark.value.trim()
    };
    const phoneOk = /^\d{10}$/.test(vals.phone);
    const pinOk = /^\d{6}$/.test(vals.pincode);

    setFieldInvalid("field-name", !vals.name);
    setFieldInvalid("field-phone", !phoneOk);
    setFieldInvalid("field-address", !vals.address);
    setFieldInvalid("field-city", !vals.city);
    setFieldInvalid("field-pincode", !pinOk);

    const valid = !!(vals.name && phoneOk && vals.address && vals.city && pinOk);
    return { valid, vals };
  }

  function buildOrderText(){
    const summary = getCartSummary();
    let text = baseText;
    if(!summary.lines.length){
      return encodeURIComponent(text);
    }
    text += ":%0A" + summary.lines.map(l => "- " + encodeURIComponent(l)).join("%0A") +
            "%0ATotal: " + encodeURIComponent(rupee(summary.total));

    const vals = {
      name: custFields.name.value.trim(),
      phone: custFields.phone.value.trim(),
      address: custFields.address.value.trim(),
      city: custFields.city.value.trim(),
      pincode: custFields.pincode.value.trim(),
      landmark: custFields.landmark.value.trim()
    };
    const payMethod = currentPayMethod();
    const upiRef = upiRefInput.value.trim();

    text += "%0A%0ADeliver to:%0A" + encodeURIComponent(vals.name + ", " + vals.phone) +
            "%0A" + encodeURIComponent(vals.address + ", " + vals.city + " - " + vals.pincode);
    if(vals.landmark) text += "%0ALandmark: " + encodeURIComponent(vals.landmark);

    const lat = document.getElementById("cust-lat").value;
    const lng = document.getElementById("cust-lng").value;
    if(lat && lng){
      text += "%0AMap pin: " + encodeURIComponent("https://maps.google.com/?q=" + lat + "," + lng);
    }

    text += "%0APayment: " + encodeURIComponent(
      payMethod === "upi"
        ? "UPI" + (upiRef ? " (Ref: " + upiRef + ")" : " - screenshot/reference to follow")
        : "Cash on Delivery"
    );
    return text;
  }

  function updateOrder(){
    const summary = getCartSummary();
    currentTotal = summary.total;

    if(summary.lines.length){
      orderLabel.textContent = "Order " + summary.count + " item" + (summary.count > 1 ? "s" : "") + " · " + rupee(summary.total);
      ctaNote.textContent = "Fill in your delivery details above, then send your order.";
    } else {
      orderLabel.textContent = "Order on WhatsApp";
      ctaNote.textContent = "Tip: pick quantities above and your order list is sent automatically.";
    }

    pillCount.textContent = summary.count;
    pillText.textContent = "View order · " + rupee(summary.total);
    pill.classList.toggle("show", summary.count > 0);

    if(currentPayMethod() === "upi") updateUpiQr(currentTotal);
  }

  function handleOrderClick(e){
    const summary = getCartSummary();
    if(summary.count > 0){
      const { valid } = validateDelivery();
      if(!valid){
        e.preventDefault();
        deliveryErrorBanner.classList.add("show");
        deliverySection.scrollIntoView({ behavior: "smooth", block: "center" });
        return;
      }
    }
    deliveryErrorBanner.classList.remove("show");
    if(summary.count > 0) logOrderToSheet(summary);
    e.currentTarget.href = "https://wa.me/" + PHONE + "?text=" + buildOrderText();
  }

  function logOrderToSheet(summary){
    if(!ORDER_LOG_URL || ORDER_LOG_URL.indexOf("PASTE_YOUR") === 0) return;
    const payMethod = currentPayMethod();
    const upiRef = upiRefInput.value.trim();
    const payload = {
      timestamp: new Date().toISOString(),
      name: custFields.name.value.trim(),
      phone: custFields.phone.value.trim(),
      address: custFields.address.value.trim(),
      city: custFields.city.value.trim(),
      pincode: custFields.pincode.value.trim(),
      landmark: custFields.landmark.value.trim(),
      items: summary.lines.join(" | "),
      total: summary.total,
      paymentMethod: payMethod === "upi" ? "UPI" : "Cash on Delivery",
      upiRef: upiRef,
      mapLink: (custLat.value && custLng.value) ? ("https://maps.google.com/?q=" + custLat.value + "," + custLng.value) : ""
    };
    // Fire-and-forget: Apps Script web apps don't return CORS headers, so we
    // use no-cors mode. We can't read a response, but the row still gets
    // written — this never blocks or delays sending the WhatsApp order.
    try{
      fetch(ORDER_LOG_URL, {
        method: "POST",
        mode: "no-cors",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify(payload)
      }).catch(function(){ /* ignore — logging is best-effort */ });
    }catch(err){ /* ignore */ }
  }

  orderBtn.addEventListener("click", handleOrderClick);
  pill.addEventListener("click", handleOrderClick);

  [custFields.name, custFields.phone, custFields.address, custFields.city, custFields.pincode].forEach(function(el){
    el.addEventListener("input", function(){
      const field = el.closest(".d-field");
      if(field) field.classList.remove("invalid");
      if(!document.querySelector(".d-field.invalid")){
        deliveryErrorBanner.classList.remove("show");
      }
    });
  });

  // ---- Map location picker ----
  // Uses OpenStreetMap (Leaflet) + the free Nominatim geocoding service — no API key
  // needed. For higher-traffic production use, consider a paid geocoding provider
  // (Google Geocoding, Mapbox, LocationIQ) for better rate limits and reliability.
  const mapPickBtn = document.getElementById("map-pick-btn");
  const mapModal = document.getElementById("map-modal");
  const mapBackBtn = document.getElementById("map-back-btn");
  const mapSearchInput = document.getElementById("map-search-input");
  const mapSearchBtn = document.getElementById("map-search-btn");
  const mapCurrentLocBtn = document.getElementById("map-current-loc-btn");
  const mapConfirmBtn = document.getElementById("map-confirm-btn");
  const mapAddressTitle = document.getElementById("map-address-title");
  const mapAddressSub = document.getElementById("map-address-sub");
  const custLat = document.getElementById("cust-lat");
  const custLng = document.getElementById("cust-lng");
  const mapApproxNote = document.getElementById("map-approx-note");

  const DEFAULT_MAP_CENTER = [17.4646, 78.5344]; // approx. Sainikpuri, Secunderabad
  let leafletMap = null;
  let geocodeTimer = null;
  let selectedLocation = null;

  function markLocationApprox(isApprox){
    mapApproxNote.classList.toggle("show", !!isApprox);
  }

  function ensureMap(){
    if(leafletMap || typeof L === "undefined") return;
    leafletMap = L.map("map-canvas", { zoomControl:false }).setView(DEFAULT_MAP_CENTER, 15);
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      maxZoom:19,
      attribution:"&copy; OpenStreetMap contributors"
    }).addTo(leafletMap);
    L.control.zoom({ position:"bottomright" }).addTo(leafletMap);
    leafletMap.on("moveend", scheduleReverseGeocode);
  }

  function scheduleReverseGeocode(){
    clearTimeout(geocodeTimer);
    mapConfirmBtn.disabled = true;
    mapAddressTitle.textContent = "Locating\u2026";
    mapAddressSub.textContent = "";
    markLocationApprox(false);
    geocodeTimer = setTimeout(reverseGeocodeCenter, 700);
  }

  // Small helper: fetch with a timeout so a stalled request doesn't leave
  // the UI stuck on "Locating..." forever.
  function fetchWithTimeout(url, ms){
    const controller = new AbortController();
    const timer = setTimeout(function(){ controller.abort(); }, ms || 7000);
    return fetch(url, { signal: controller.signal }).finally(function(){ clearTimeout(timer); });
  }

  // Nominatim's usage policy asks apps to identify themselves (reduces the
  // chance of being silently rate-limited) — https://operations.osmfoundation.org/policies/nominatim/
  const GEOCODE_CONTACT = "vasistanaturals@gmail.com";

  function reverseGeocodeCenter(){
    if(!leafletMap) return;
    const center = leafletMap.getCenter();

    function applyResult(title, sub, city, pincode, full, approx){
      selectedLocation = { full: full, city: city, pincode: pincode, lat: center.lat, lng: center.lng };
      mapAddressTitle.textContent = title;
      mapAddressSub.textContent = sub;
      mapConfirmBtn.disabled = false;
      // Free geocoding services don't have official India Post PIN-code
      // boundaries, so city/pincode can be off — flag it so the customer checks.
      markLocationApprox(!!approx);
    }

    // Primary: Nominatim (OpenStreetMap) — generally the more detailed of the
    // two free options for Indian road/locality names.
    const nomUrl = "https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=" + center.lat +
                "&lon=" + center.lng + "&zoom=18&addressdetails=1&email=" + encodeURIComponent(GEOCODE_CONTACT);
    fetchWithTimeout(nomUrl, 6000)
      .then(function(r){ if(!r.ok) throw new Error("bad status " + r.status); return r.json(); })
      .then(function(data){
        const addr = data.address || {};
        const title = addr.amenity || addr.building || addr.road || addr.suburb || addr.neighbourhood || "Selected location";
        const parts = [addr.road, addr.suburb || addr.neighbourhood, addr.village || addr.town || addr.city, addr.state, addr.postcode].filter(Boolean);
        const sub = parts.join(", ") || data.display_name || "";
        applyResult(
          title, sub,
          addr.city || addr.town || addr.village || addr.suburb || addr.neighbourhood || "",
          addr.postcode || "",
          data.display_name || (title + (sub ? ", " + sub : "")),
          true
        );
      })
      // Fallback: BigDataCloud's client-side reverse-geocode endpoint, in case
      // Nominatim is unreachable (no key needed, reliable CORS support).
      .catch(function(){
        const bdcUrl = "https://api.bigdatacloud.net/data/reverse-geocode-client?latitude=" + center.lat +
                       "&longitude=" + center.lng + "&localityLanguage=en";
        return fetchWithTimeout(bdcUrl, 6000)
          .then(function(r){ if(!r.ok) throw new Error("bad status " + r.status); return r.json(); })
          .then(function(data){
            const title = data.locality || data.city || data.principalSubdivision || "Selected location";
            const parts = [
              data.locality && data.locality !== title ? data.locality : null,
              data.city && data.city !== title ? data.city : null,
              data.principalSubdivision,
              data.postcode,
              data.countryName
            ].filter(Boolean);
            const sub = parts.join(", ");
            applyResult(title, sub, data.city || data.locality || "", data.postcode || "", [title, sub].filter(Boolean).join(", "), true);
          });
      })
      .catch(function(){
        selectedLocation = { full:"", city:"", pincode:"", lat:center.lat, lng:center.lng };
        mapAddressTitle.textContent = "Couldn't auto-detect address";
        mapAddressSub.textContent = "That's OK — confirm this pin and type your address below.";
        mapConfirmBtn.disabled = false;
        markLocationApprox(false);
      });
  }

  function openMapModal(){
    mapModal.classList.add("open");
    document.body.style.overflow = "hidden";
    const firstOpen = !leafletMap;
    ensureMap();
    setTimeout(function(){
      if(!leafletMap) return;
      leafletMap.invalidateSize();
      if(firstOpen && navigator.geolocation){
        // Try to auto-fetch the customer's real location & address on first open,
        // so they don't have to tap "Current location" manually.
        mapAddressTitle.textContent = "Finding your location\u2026";
        navigator.geolocation.getCurrentPosition(function(pos){
          leafletMap.setView([pos.coords.latitude, pos.coords.longitude], 17);
        }, function(){
          // Permission denied / unavailable — fall back to reverse-geocoding
          // whatever the default map center is.
          scheduleReverseGeocode();
        }, { enableHighAccuracy:true, timeout:6000 });
      } else {
        scheduleReverseGeocode();
      }
    }, 60);
  }

  function closeMapModal(){
    mapModal.classList.remove("open");
    document.body.style.overflow = "";
  }

  function doMapSearch(){
    const q = mapSearchInput.value.trim();
    if(!q || !leafletMap) return;
    fetch("https://nominatim.openstreetmap.org/search?format=jsonv2&q=" + encodeURIComponent(q) + "&limit=1&countrycodes=in")
      .then(function(r){ return r.json(); })
      .then(function(results){
        if(results && results[0]){
          leafletMap.setView([parseFloat(results[0].lat), parseFloat(results[0].lon)], 16);
        }
      });
  }

  mapPickBtn.addEventListener("click", openMapModal);
  mapBackBtn.addEventListener("click", closeMapModal);
  mapSearchBtn.addEventListener("click", doMapSearch);
  mapSearchInput.addEventListener("keydown", function(e){
    if(e.key === "Enter"){ e.preventDefault(); doMapSearch(); }
  });

  mapCurrentLocBtn.addEventListener("click", function(){
    if(!navigator.geolocation || !leafletMap) return;
    mapCurrentLocBtn.disabled = true;
    navigator.geolocation.getCurrentPosition(function(pos){
      leafletMap.setView([pos.coords.latitude, pos.coords.longitude], 17);
      mapCurrentLocBtn.disabled = false;
    }, function(){
      mapCurrentLocBtn.disabled = false;
      alert("Couldn't get your current location. Please allow location access or search above.");
    }, { enableHighAccuracy:true, timeout:8000 });
  });

  mapConfirmBtn.addEventListener("click", function(){
    if(!selectedLocation) return;
    if(selectedLocation.full) custFields.address.value = selectedLocation.full;
    if(selectedLocation.city) custFields.city.value = selectedLocation.city;
    if(selectedLocation.pincode) custFields.pincode.value = selectedLocation.pincode;
    custLat.value = selectedLocation.lat;
    custLng.value = selectedLocation.lng;
    ["field-address", "field-city", "field-pincode"].forEach(function(id){ setFieldInvalid(id, false); });
    if(!document.querySelector(".d-field.invalid")) deliveryErrorBanner.classList.remove("show");
    closeMapModal();
  });

  updateOrder();
})();
